"""Original energetic models, experimental calculations and thermodynamic reasoning."""
import math
from decimal import Decimal, ROUND_HALF_UP
from common import Bank,p,step,f,v,quantity as u,svg,text,line,graph
B=Bank('R1','reactivity-1',{'R1.1':'Measuring enthalpy changes','R1.2':'Energy cycles in reactions','R1.3':'Energy from fuels','R1.4':'Entropy and spontaneity'})
R=8.31
def chem(s):return r'$\mathrm{'+s+'}$'
def table(headers,rows):return '| '+' | '.join(headers)+' |\n|'+'|'.join(['---']*len(headers))+'|\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in rows)
def calorimeter():
    z=text(400,27,'Insulated solution calorimeter',18)
    z+='<path d="M225 110 L225 315 L570 315 L570 110" fill="#f4fafc" stroke="#31556b" stroke-width="3"/>'
    z+=line(215,110,580,110)+line(360,65,360,255,'#b04c45',5)
    z+=text(360,50,'thermometer',15)+text(397,195,'mixed solution',17)
    z+=line(570,250,650,250)+text(660,255,'insulation',14,'start')
    z+=text(400,355,'Neglect the heat capacity of the cup unless stated otherwise.',14)
    return svg(z)
def hess(a,b,c,direct,first,second,solved=False):
    z=text(400,26,'Enthalpy cycle (schematic, not an energy scale)',16)
    z+=text(175,94,a,16)+text(625,94,b,16)+text(400,290,c,16)
    z+=line(240,110,550,110,arrow=True)+text(400,88,direct if solved else 'target ΔH = ?',15)
    z+=line(185,125,340,260,arrow=True)+text(155,210,first,14)
    z+=line(625,125,460,260,arrow=True)+text(650,210,second,14)
    return svg(z)

# R1.1: six independent task families; all are SL content.
for i,(mass,dt) in enumerate([(100,5.2),(150,3.6),(200,4.1),(125,6.4)]):
    q=mass*4.18*dt/1000
    B.add('R1.1','sl','easy','Heat gained by a solution',f'A well-insulated cup contains {u(mass,"g")} of solution. Its temperature increases by {u(dt,"K")}. Take its specific heat capacity as '+u(4.18,r'J\,g^{-1}\,K^{-1}')+'. What heat is gained by the solution?',correct=u(q,'kJ'),distractors=[u(q*1000,'kJ'),u(q/4.18,'kJ'),u(-q,'kJ')],reasoning=r'$q=mc\Delta T$ gives '+u(q,'kJ')+'. A temperature rise means that the solution gains heat.')
for vol,c,dt in [(25,.8,5.1),(30,1.2,7.2),(40,.5,3.1),(20,1.5,8.5)]:
    heat=2*vol*4.18*dt;n=vol*c/1000;dh=-heat/n/1000
    B.add('R1.1','sl','medium','Neutralization in an insulated cup',f'Equal volumes, each {u(vol,"cm^3")}, of hydrochloric acid and sodium hydroxide both have concentration '+u(c,r'mol\,dm^{-3}')+f'. They react completely in the illustrated cup, with a temperature increase of {u(dt,"K")}. Assume the mixed solution has density '+u(1,r'g\,cm^{-3}')+', specific heat capacity '+u(4.18,r'J\,g^{-1}\,K^{-1}')+', and negligible heat loss.',parts=[p('Calculate the heat gained by the solution.',step(f'The total solution mass is {u(2*vol,"g")}; apply '+r'$q=mc\Delta T$.','M1'),step('The heat gained is '+u(heat,'J')+'.')),p('Calculate the enthalpy change per mole of water formed.',step('The amount of water formed is '+u(n,'mol')+'.','M1'),step(r'$\Delta H=-q/n=$ '+u(dh,r'kJ\,mol^{-1}')+'. The reaction loses the heat gained by the solution.'))],diagram=calorimeter())
for massfuel,water,dt,M in [(.62,200,12.5,46.0),(.48,150,11.2,32.0),(.82,250,14.2,60.0),(.73,200,16.1,74.0)]:
    heat=water*4.18*dt;dh=-heat/(massfuel/M)/1000
    B.add('R1.1','sl','medium','A combustion calorimetry measurement',f'In a constructed trial, {u(massfuel,"g")} of an alcohol of molar mass '+u(M,r'g\,mol^{-1}')+f' burns completely below a copper can. The {u(water,"g")} of water in the can warms by {u(dt,"K")}. Use '+u(4.18,r'J\,g^{-1}\,K^{-1}')+' for water and initially neglect all other heat capacities.',parts=[p('Calculate the experimental molar enthalpy of combustion.',step(r'$q_{\mathrm{water}}=mc\Delta T=$ '+u(heat,'J',sig=6)+'.','M1'),step('The amount of fuel burnt is '+u(massfuel/M,'mol')+'.','M1'),step(r'$\Delta H_{\mathrm{c}}=-q_{\mathrm{water}}/n=$ '+u(dh,r'kJ\,mol^{-1}')+'.')),p('Explain how heat absorbed by the copper can affects this experimental result.',step('Some released heat warms the can. Ignoring this energy underestimates the heat released, so the reported enthalpy is less negative than the value accounting for the can.','R1'))])
for initial,intercept,slope,mass,n in [(20,27.4,-.12,100,.05),(22,28.9,-.09,120,.06),(19,26.8,-.10,80,.04),(23,30.1,-.08,150,.075)]:
    times=[2,3,4,5];temps=[intercept+slope*t for t in times];dh=-mass*4.18*(intercept-initial)/n/1000
    data=table(['Time after mixing / min','Temperature / °C'],[(t,f(T,4)) for t,T in zip(times,temps)])
    B.add('R1.1','sl','hard','Extrapolating a cooling trace',f'A constructed experiment mixes reagents at time zero. Before mixing both were at {initial} °C. After the reaction has finished, the following linear cooling data are recorded. Total solution mass is {u(mass,"g")}; {u(n,"mol")} reacts. Use '+u(4.18,r'J\,g^{-1}\,K^{-1}')+'.\n\n'+data,question_type='data-based',parts=[p('Use the linear post-reaction trend to estimate the temperature at time zero and the corrected temperature rise.',step('The cooling gradient is '+u(slope,r'K\,min^{-1}')+'; extrapolate the same line to zero time.','M1'),step(f'The intercept is {f(intercept,4)} °C, giving '+u(intercept-initial,'K')+' for the corrected rise.')),p('Calculate the corrected molar enthalpy change.',step(r'$\Delta H=-mc\Delta T/n=$ '+u(dh,r'kJ\,mol^{-1}')+'.')),p('State the purpose and one limitation of this correction.',step('It estimates heat lost during the reaction by extending the cooling trend backwards.','R1'),step('It assumes that the cooling behaviour after the reaction represents heat loss during mixing and reaction; this may fail if heat-loss rate or the apparatus conditions change.','R1'))],diagram=graph('Measured post-reaction temperatures','Time after mixing / min','Temperature / °C',list(zip(times,temps)),y_limits=(math.floor(intercept)-1,math.floor(intercept)+1)))
for masssolute,M,masssoln,fall in [(4,60.0,104,2.6),(3.5,74.0,103.5,2.1),(5.2,80.0,125.2,3.2),(6.0,100.0,156,2.4)]:
    n=masssolute/M;q=-masssoln*4.18*fall;dh=-q/n/1000
    B.add('R1.1','sl','medium','An endothermic dissolution',f'A constructed soluble molecular solid has molar mass '+u(M,r'g\,mol^{-1}')+f'. A {u(masssolute,"g")} sample dissolves completely to form {u(masssoln,"g",sig=6)} of solution, whose temperature falls by {u(fall,"K")}. Assume specific heat capacity '+u(4.18,r'J\,g^{-1}\,K^{-1}')+' and no heat exchange with the surroundings.',parts=[p('Calculate the heat change of the solution and the molar enthalpy of dissolution.',step(r'$q_{\mathrm{solution}}=mc\Delta T=$ '+u(q,'J')+', since the temperature change is negative.','M1'),step('The amount dissolved is '+u(n,'mol')+'.','M1'),step(r'$\Delta H_{\mathrm{sol}}=-q_{\mathrm{solution}}/n=$ '+u(dh,r'kJ\,mol^{-1}')+'.')),p('Explain the sign of this enthalpy change.',step('The dissolving system absorbs energy from the solution; its enthalpy increases, so dissolution is endothermic and the value is positive.','R1'))],diagram=calorimeter())
for dt,error,mass,n in [(5,.1,100,.05),(4,.2,120,.04),(8,.1,150,.06),(6,.15,200,.08)]:
    dh=-mass*4.18*dt/n/1000;absunc=float((Decimal(str(mass))*Decimal("4.18")*Decimal(str(2*error))/Decimal(str(n))/Decimal(1000)).quantize(Decimal("0.01"),rounding=ROUND_HALF_UP))
    B.add('R1.1','sl','hard','Temperature uncertainty in calorimetry',f'Two temperature readings each have maximum absolute uncertainty ±{f(error)} K. Their difference is {u(dt,"K")}. For this exercise treat the {u(mass,"g")} solution mass, its specific heat capacity '+u(4.18,r'J\,g^{-1}\,K^{-1}')+f' and the reacting amount {u(n,"mol")} as exact. Assume no systematic heat loss.',question_type='data-based',parts=[p('Determine the maximum absolute uncertainty and percentage uncertainty of the temperature rise.',step('For a difference, add the absolute uncertainties: '+u(2*error,'K')+'.','M1'),step('The percentage uncertainty is '+u(100*2*error/dt,r'\%')+'.')),p('Calculate the molar enthalpy change and its maximum absolute uncertainty from temperature alone.',step('The enthalpy is '+u(dh,r'kJ\,mol^{-1}')+'.','M1'),step('Multiplication by exact factors preserves percentage uncertainty; the absolute uncertainty is ±'+u(absunc,r'kJ\,mol^{-1}')+'.'))])

# R1.2: mean bonds and Hess (SL), then standard cycles and Born–Haber (HL).
for X,D,HX in [('F',158,565),('Cl',243,431),('Br',193,366),('I',151,299)]:
    dh=436+D-2*HX
    B.add('R1.2','sl','medium','Average bond enthalpies',chem('H_2(g)')+' reacts with '+chem(X+'_2(g)')+' to form two moles of '+chem('H'+X+'(g)')+'. Use the following average bond enthalpies, all in '+r'$\mathrm{kJ\,mol^{-1}}$: '+f'H–H 436, {X}–{X} {D}, H–{X} {HX}. Estimate the reaction enthalpy as written.',correct=u(dh,r'kJ\,mol^{-1}'),distractors=[u(-dh,r'kJ\,mol^{-1}'),u(436+D-HX,r'kJ\,mol^{-1}'),u(436+D+2*HX,r'kJ\,mol^{-1}')],reasoning=r'Bonds broken minus bonds formed gives $436+'+str(D)+'-2('+str(HX)+')='+str(dh)+r'\,\mathrm{kJ\,mol^{-1}}$.')
for fuel,broken,formed in [('CH_4',[(4,413),(2,498)],[(2,805),(4,463)]),('C_2H_6',[(6,413),(1,347),(3.5,498)],[(4,805),(6,463)]),('C_2H_4',[(4,413),(1,614),(3,498)],[(4,805),(4,463)]),('CH_3OH',[(3,413),(1,358),(1,463),(1.5,498)],[(2,805),(4,463)])]:
    Ebreak=sum(n*h for n,h in broken);Eform=sum(n*h for n,h in formed);dh=Ebreak-Eform
    B.add('R1.2','sl','hard','Bond inventory for gaseous combustion','One mole of gaseous '+chem(fuel)+' burns completely to gaseous carbon dioxide and water vapour. Use these mean bond enthalpies in '+r'$\mathrm{kJ\,mol^{-1}}$: C–H 413, C–C 347, C=C 614, C–O 358, O–H 463, O=O 498, and C=O in carbon dioxide 805. Estimate the enthalpy of combustion.',parts=[p('Determine the energy needed to break the reactant bonds and the energy released by forming product bonds.',step('Use the balanced combustion equation to count every bond, including the oxygen molecules.','M1'),step('Energy to break bonds: '+u(Ebreak,r'kJ\,mol^{-1}')+'; energy released on formation: '+u(Eform,r'kJ\,mol^{-1}')+'.')),p('Calculate the estimated enthalpy change and explain why it is an estimate.',step(r'$\Delta H=E_{\mathrm{broken}}-E_{\mathrm{formed}}=$ '+u(dh,r'kJ\,mol^{-1}')+'.'),step('Mean bond enthalpies are averaged gas-phase values; actual bond environments can differ. The calculation also refers to gaseous water, not liquid water.','R1'))])
hesscases=[
 (r'$\mathrm{C(s)+\tfrac12O_2(g)\to CO(g)}$',-110.5,r'$\mathrm{CO(g)+\tfrac12O_2(g)\to CO_2(g)}$',-283.0,r'$\mathrm{C(s)+O_2(g)\to CO_2(g)}$',-393.5,'Add the two equations; the intermediate carbon monoxide cancels.'),
 (r'$\mathrm{H_2(g)+Cl_2(g)\to2HCl(g)}$',-184.6,r'$\mathrm{H_2(g)+Br_2(g)\to2HBr(g)}$',-72.8,r'$\mathrm{2HBr(g)+Cl_2(g)\to2HCl(g)+Br_2(g)}$',-111.8,'Reverse the second equation and add it to the first.'),
 (r'$\mathrm{C(s)+O_2(g)\to CO_2(g)}$',-394,r'$\mathrm{2CO(g)+O_2(g)\to2CO_2(g)}$',-566,r'$\mathrm{2C(s)+O_2(g)\to2CO(g)}$',-222,'Double the first equation, then reverse and add the second.'),
 (r'$\mathrm{N_2(g)+O_2(g)\to2NO(g)}$',181,r'$\mathrm{2NO(g)+O_2(g)\to2NO_2(g)}$',-114,r'$\mathrm{N_2(g)+2O_2(g)\to2NO_2(g)}$',67,'Add the equations; the two moles of nitrogen monoxide cancel.')]
for a,ha,b,hb,target,ans,method in hesscases:
    B.add('R1.2','sl','medium','Combining thermochemical equations','Use these rounded enthalpy changes for the equations as written:\n\n'+a+': '+u(ha,r'kJ\,mol^{-1}',sig=6)+'\n\n'+b+': '+u(hb,r'kJ\,mol^{-1}',sig=6)+'\n\nThe target reaction is '+target+'.',parts=[p('Use Hess’s law to determine the target reaction enthalpy.',step(method,'M1'),step('Apply the same multipliers and sign changes to the enthalpy values.','M1'),step('The target enthalpy change is '+u(ans,r'kJ\,mol^{-1}')+'.')),p('Explain why this method is valid.',step('Enthalpy is a state function; with the same initial and final states, the overall enthalpy change is independent of the reaction route.','R1'))])
fuels=[('CH_4(g)',1,4,16.0,-74.8),('C_2H_5OH(l)',2,6,46.0,-277.7),('CH_3OH(l)',1,4,32.0,-238.7),('C_3H_8(g)',3,8,44.0,-104.7)]
